<script setup>
import { computed, ref, watch } from 'vue'
const props=defineProps({provider:Object,monitors:Array});defineEmits(['monitor','plans'])
const selectedCategory=ref('');const categories=computed(()=>monitor.value?.categories||props.provider.categories||[]);
const monitor=computed(()=>props.monitors.find(m=>m.providerId===props.provider.id))
watch(categories,value=>{if(!value.some(c=>c.id===selectedCategory.value))selectedCategory.value=value[0]?.id||''},{immediate:true})
</script>
<template><article class="provider-card"><div class="provider-top"><h3>{{provider.name}}</h3><span class="badge">{{provider.adapterKey}}</span></div><p class="meta">Adapter {{provider.adapterVersion||'0.0.0'}}</p><div v-if="categories.length>6" class="provider-category-picker"><div class="field"><label :for="`provider-category-${provider.id}`">浏览分类 · {{categories.length}} 类</label><select :id="`provider-category-${provider.id}`" v-model="selectedCategory"><option v-for="category in categories" :key="category.id" :value="category.id">{{category.name}} · {{category.planCount??0}} 个套餐{{category.lastError?' · 探测异常':''}}</option></select></div><button class="button secondary" @click="$emit('plans',selectedCategory)">查看分类套餐</button></div><div v-else-if="categories.length" class="provider-categories"><button v-for="category in monitor?.categories || provider.categories" :key="category.id" class="button ghost" @click="$emit('plans', category.id)">{{category.name}}<span class="meta">{{category.planCount === undefined ? '等待探测' : `${category.planCount} 个套餐`}}</span><span v-if="category.lastError" class="category-warning">探测异常</span></button></div><div class="bar"><span :style="{width:monitor?.enabled?'100%':'0%'}"></span></div><div class="card-actions"><span class="meta">{{monitor?.enabled?'监控中':'未监控'}}</span><div class="button-pair"><button v-if="!provider.categories?.length" class="button ghost" @click="$emit('plans')">套餐</button><button class="button secondary" @click="$emit('monitor')">{{monitor?'编辑监控':'添加监控'}}</button></div></div></article></template>
